WITH p AS (
SELECT
 if(block_date BETWEEN '2026-08-10' AND '2026-08-31', 'A', if(block_date BETWEEN '2026-09-01' AND '2026-09-24', 'B', 'X')) AS per,
 swaps, volume_usd
FROM fct_pool_daily WHERE pool_address = '0x88e6a0c2ddd26feeb64f039a2c41296fcb3f5640'
), t AS (
SELECT per, sum(volume_usd)/sum(swaps) AS avg_swap FROM p WHERE per IN ('A','B') GROUP BY per
)
SELECT (maxIf(avg_swap, per='B') - maxIf(avg_swap, per='A')) / maxIf(avg_swap, per='A') * 100 AS pct_change FROM t

